const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Halema‘uma‘u Crater coordinates (approximate center of Kilauea's summit caldera)
  const halemaumau = ee.Geometry.Point([-155.286, 19.425]);
  const bufferRadiusKm = 10;
  const analysisRegion = halemaumau.buffer(bufferRadiusKm * 1000); // 10 km buffer

  // Date and Time: July 20, 2025 at 10:44 am local time (HST -10)
  // 10:44 AM HST = 20:44 UTC
  // Sentinel-2 overpass is typically around 10:30-11:00 AM local time.
  // We'll search for a 2-hour window around the requested UTC time.
  const date = '2025-07-20';
  const startTime = ee.Date(date).advance(20, 'hour').advance(0, 'minute'); // Start of search window (20:00 UTC)
  const endTime = ee.Date(date).advance(22, 'hour').advance(0, 'minute');   // End of search window (22:00 UTC)

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(analysisRegion)
    .filterDate(startTime, endTime)
    .sort('CLOUD_COVERAGE_ASSESSMENT'); // Prioritize less cloudy images

  const collectionSize = await collection.size().getInfo();

  if (collectionSize === 0) {
    console.log("No Sentinel-2 L2A images found for July 20, 2025, between 20:00 and 22:00 UTC near Halema‘uma‘u.");
    console.log("C1"); // Empty Collection
    return;
  }

  // Get the least cloudy image, or the first one if sorting doesn't matter much for a single day.
  let image = collection.first();
  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd HH:mm:ss').getInfo();
  const cloudCoverage = image.get('CLOUD_COVERAGE_ASSESSMENT').getInfo();
  console.log(`Image selected: ${imageDate}, Cloud Coverage: ${cloudCoverage.toFixed(2)}%`);

  // Scale factor for Sentinel-2 surface reflectance bands
  const S2_SCALE_FACTOR = 0.0001;

  // 3. Cloud Masking (using SCL band for general clouds)
  // SCL values: 3 (cloud shadow), 8 (medium probability cloud), 9 (high probability cloud), 10 (cirrus)
  const scl = image.select('SCL');
  const cloudMask = scl.eq(3).or(scl.eq(8)).or(scl.eq(9)).or(scl.eq(10));
  const generalClouds = image.updateMask(cloudMask);

  // 4. Plume Detection (simplified approach using spectral properties of ash/plume)
  // Volcanic plumes often have distinct spectral signatures.
  // For ash: Often high reflectance in visible, lower in SWIR compared to water clouds.
  // B4 (Red), B8 (NIR), B11 (SWIR1), B12 (SWIR2)
  // A simple index might involve B4 and B12: Plume Index = (B4 - B12) / (B4 + B12)
  // Let's try to detect bright features above a certain threshold that are not already masked as general clouds.
  // Using B4 (Red) as a proxy for brightness, and B12 (SWIR2) to help differentiate from some clouds.

  // Using a 'Plume Index' (similar to Normalized Difference Dust Index - NDDI for ash)
  // NDDI = (B4 - B12) / (B4 + B12)
  // Ash can have a positive NDDI, while water clouds might be negative or near zero.
  const b4 = image.select('B4').multiply(S2_SCALE_FACTOR);
  const b12 = image.select('B12').multiply(S2_SCALE_FACTOR);

  const plumeIndex = b4.subtract(b12).divide(b4.add(b12)).rename('plume_index');

  // We are looking for high PI values (e.g., > 0.1 or 0.2, experiment needed) within the region,
  // that are also bright in visible bands (e.g., B4 > 0.15) and not flagged as general clouds.
  const brightnessThreshold = 0.15; // Reflectance > 15% in Red band
  const plumeIndexThreshold = 0.05; // Plume Index > 0.05 (threshold to separate from water clouds/land)

  // Ensure plume is distinct from general clouds detected by SCL band
  // AND is significantly bright and has the plume spectral signature
  const potentialPlumeMask = plumeIndex.gt(plumeIndexThreshold)
                             .and(b4.gt(brightnessThreshold))
                             .and(cloudMask.not()); // Ensure it's not already classified as general cloud by SCL

  const volcanicPlume = image.updateMask(potentialPlumeMask);

  // 5. Area Calculation (using pixel counts and scale)
  const scale = 20; // Sentinel-2 B4, B8, B11, B12 are at 20m resolution. SCL is 20m.

  // Calculate pixel count for general clouds
  const cloudPixelCount = generalClouds.select('SCL').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('SCL').getInfo();

  // Calculate pixel count for volcanic plume
  const plumePixelCount = volcanicPlume.select('B4').reduceRegion({ // Use any band in plume masked image
    reducer: ee.Reducer.count(),
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('B4').getInfo();

  // Validate pixel counts
  if (cloudPixelCount === null || plumePixelCount === null) {
      console.log("Calculation of pixel counts failed.");
      console.log("C3");
      return;
  }
  if (cloudPixelCount === 0 && plumePixelCount === 0) {
      console.log("No valid cloud or plume pixels found after processing.");
      console.log("C2");
      return;
  }

  // Convert pixel counts to area in km^2
  const pixelArea = scale * scale / 1e6; // Area of one pixel in km^2
  const cloudAreaKm2 = cloudPixelCount * pixelArea;
  const plumeAreaKm2 = plumePixelCount * pixelArea;

  console.log(`Cloud Area (10km radius): ${cloudAreaKm2.toFixed(2)} km^2 (Pixels: ${cloudPixelCount})`);
  console.log(`Plume Area (10km radius): ${plumeAreaKm2.toFixed(2)} km^2 (Pixels: ${plumePixelCount})`);

  // 6. Validation & Final Answer
  if (cloudAreaKm2 === null || plumeAreaKm2 === null || isNaN(cloudAreaKm2) || isNaN(plumeAreaKm2)) {
    console.log("C3"); // Calculation failed
  } else if (cloudAreaKm2 > plumeAreaKm2) {
    console.log("A"); // Yes, clouds covered a larger area
  } else {
    console.log("B"); // No, clouds did not cover a larger area (or were equal)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
